  "nav.docs": "文档",
  "docs.title": "文档",
  "docs.subtitle": "完整的 GameIndex 使用手册——从首次导入到 Steam Deck 调校，涵盖每一个界面、功能与快捷键。你可以搜索、跳转，或从头读到尾。",
  "docs.toc": "目录",
  "docs.onThisPage": "本页导读",
  "docs.quickStart": "快速开始",
  "docs.quickStartSubtitle": "几分钟内掌握 GameIndex 核心功能与基础配置。",
  "docs.relatedTopics": "相关主题",
  "docs.expandAll": "展开全部",
  "docs.home.title": "首页面板",
  "docs.home.body": "**首页** 是 GameIndex 的面板：最近玩过什么、正在下载什么、接下来值得看什么。它是默认打开的页面。\n\n## 面板内容\n- **聚光灯主视觉**：把最近的游戏放大展示，可直接回到上次的进度。\n- **速览统计**：一眼看到库的规模与游玩时长。\n- 左栏 **小组件**：快速启动、每周活动、成就与好友动态。\n- **继续游玩** 与 **最近添加** 分组，继续游戏或检查新导入只需一次点击。\n- 右侧为 **进行中的下载**、**愿望单**、**优惠** 与 **新闻**。\n\n## 按你的习惯调整\n- 点击面板上方的 **自定义** 可逐项开关各个区块。\n- 在 **简化界面模式** 下，密集面板会换成简短的欢迎栏，带有 **浏览商店** 与 **你的游戏库** 两个按钮。\n- 启动时打开哪个页面，可在 **设置 → 启动器 → 起始页** 中选择。\n\n> **提示：** 每个分组都支持键盘与手柄操作，因此首页也适合沙发模式下的起点。\n\n## 值得养成的日常\n- 从首页开始，先看“继续游玩”，通常立刻回答 *接下来玩什么*。\n- 导入后瞄一眼“最近添加”，别让游戏一直没名字或没封面。\n- 只有一个下载任务时看下载分组即可，不必打开下载页。\n- 让愿望单保持精炼，优惠与愿望单分组才不会变成噪音。",
  "docs.globalsearch.title": "全局搜索与快速查找",
  "docs.globalsearch.body": "GameIndex 有多处搜索入口，知道该用哪一个最省时间。\n\n## 随处可用\n- **`Ctrl+K`**（或 **`Cmd+K`**），或顶部栏的 **搜索按钮**，会打开命令面板：游戏、页面、设置、操作与计算器都在同一个输入框里。\n- 输入几个字母后按 `Enter`，面板会同时搜索游戏库、商店和最近使用的命令。\n\n## 页面内搜索\n- **`/`** 会在有搜索框的页面聚焦它：商店、存储、下载、文档与设置。\n- **侧边栏搜索** 边输入边筛选游戏库，滚动时也持续生效。\n- **设置搜索** 会匹配标签页名、分区标题与关键词（如 *HDR* 或 *deadzone*），可直达某个开关。\n- **文档搜索** 会检索每篇文章的正文，因此输入 *prefix* 这样的词就能跳到完整页面。\n\n## 让结果更准确\n- 用一个有辨识度的词，胜过一句话的碎片；搜索匹配的是词，不是意图。\n- 用命令面板 **前往** 某处，用页面内搜索 **缩小** 眼前的内容。\n- 在商店里，搜索与筛选会叠加，组合结果还能作为链接分享。\n- 搜索看似为空时，先清除已启用的筛选：被隐藏的平台筛选可能挡住好结果。\n\n> **提示：** 命令面板会记住最近使用，所以同一天的第二次搜索通常只需两下按键。",
  "docs.plugins.title": "插件与搜索提供方",
  "docs.plugins.body": "插件用社区编写的下载搜索提供方扩展 GameIndex。它们是可选的 `.js` 文件，由你自己导入。\n\n## 安装插件\n1. 打开 **设置 → 插件**。\n2. 点击 **导入插件**，选择磁盘上的 `.js` 文件。\n3. GameIndex 会读取并校验文件，然后显示 **信任确认页**：名称、说明、来源链接、文件的 SHA-256 哈希值，以及一段通俗的警告。\n4. 确认信息无误后再确认；在此之前不会写入或启用任何内容。\n\n## 管理已安装插件\n- 可单独启用或停用插件而无需删除，出问题的提供方能快速关掉。\n- 不再使用的插件可以移除。\n- 列表会显示插件上次失败时报告的错误信息。\n- **批量导入** 可一次扫描多个文件，并说明哪些被跳过及原因。\n\n## 安全与排查\n- 只导入你信任的插件：插件提供的是应用会执行的代码，未知文件请当作普通下载对待。\n- 如果作者公布了 SHA-256 哈希值，安装前请与信任确认页显示的值对比。\n- 报告运行时错误的插件可以停用，以恢复正常搜索。\n- 提供方没有结果时，先确认其插件已启用，以及 API 密钥或接口地址仍然有效。\n\n> **注意：** 插件只提供下载搜索结果；信任确认页是你审视文件的机会。",
  "docs.launcher.title": "启动器、开机启动与托盘",
  "docs.launcher.body": "**设置 → 启动器** 决定应用如何启动、窗口如何表现，以及 Windows 何时请求权限。\n\n## 启动\n- **起始页**：选择启动时打开的页面 — 首页、游戏库、商店、愿望单、优惠、活动、成就、下载、存储、新闻或社区。\n- **开机自启**：随系统启动 GameIndex，让同步或下载在后台继续。\n\n## 窗口与托盘\n- **关闭到托盘**：关闭按钮只隐藏窗口而不退出，下载与游玩时长记录继续进行。\n- **启动游戏时最小化**：游戏开始时窗口自动让位。\n- **退出游戏后恢复**：游戏结束时把 GameIndex 唤回前台。\n\n## 权限请求（Windows）\n- **停用权限请求** 会隐藏以管理员身份启动时的 UAC 对话框。\n- 除非反复弹出的提示确实影响使用，否则建议保持关闭；单款游戏的 **以管理员身份运行** 始终可用。\n\n> **提示：** “关闭到托盘 + 开机自启”是兼顾常驻下载机器的常见组合。\n\n## 如何选择\n- 把起始页设为你每次最先打开的页面；其余页面用命令面板就能到达。\n- 如果更希望按关闭按钮就干净退出，请关掉关闭到托盘。\n- 在多显示器环境中，游戏抢焦点时最小化与恢复很有用。\n- 笔记本上一般建议关闭开机自启以节省电量。",
